// PRIMARY: crates/trie/trie/src/trie.rs:StorageRoot::new (lines 479-494)
// Address-to-hashed_address conversion for storage root lookup:
pub fn new(
    trie_cursor_factory: T,
    hashed_cursor_factory: H,
    address: Address,
    prefix_set: PrefixSet,
    #[cfg(feature = "metrics")] metrics: TrieRootMetrics,
) -> Self {
    Self::new_hashed(
        trie_cursor_factory,
        hashed_cursor_factory,
        keccak256(address),  // Address -> B256 via keccak256 (all 20 bytes hashed)
        prefix_set,
        #[cfg(feature = "metrics")]
        metrics,
    )
}

